function toggle(l,id,v){return`<div class="setting-row"><label>${l}</label><input id="${id}" class="toggle" type="checkbox" ${v?'checked':''}></div>`}function select(l,id,opts,v){return`<div class="setting-row"><label>${l}</label><select id="${id}">${opts.map(([x,y])=>`<option value="${x}" ${x===v?'selected':''}>${y}</option>`).join('')}</select></div>`}function input(l,id,v,t='text'){return`<div class="setting-row"><label>${l}</label><input id="${id}" type="${t}" value="${esc(v)}"></div>`}function rangeControl(l,id,v,min,max,step=.05){return`<div class="setting-row"><label>${l}</label><div class="range-wrap"><input id="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${esc(v)}"><span id="${id}-out" class="range-value">${Number(v).toFixed(2)}</span></div></div>`}
